head.script:
//
(function () {
  try {
    var saved = localStorage.getItem('fss-theme');
    var prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
    document.documentElement.setAttribute('data-theme', saved || (prefersDark ? 'dark' : 'light'));
  } catch (e) {
    document.documentElement.setAttribute('data-theme', 'light');
  }
})();
//

head.b:skin:
/*-----------------------------------------------
Blogger Template Style
Name:     Pulse Editorial 2026 (Modern News & Stories)
Version:  2.0
----------------------------------------------- */

/* Variable definitions
   ====================
   <Variable name="keycolor" description="Primary Accent" type="color" default="#2563eb" value="#2563eb"/>
   <Variable name="body.background" description="Background Color" type="background" color="#f8fafc" default="#f8fafc none repeat scroll top left" value="#f8fafc none repeat scroll top left"/>
   <Variable name="body.font" description="Body Font" type="font" default="normal normal 16px 'Inter', system-ui, -apple-system, sans-serif" value="normal normal 16px 'Inter', system-ui, -apple-system, sans-serif"/>
   <Variable name="body.text.color" description="Body Text Color" type="color" default="#0f172a" value="#0f172a"/>
   <Variable name="link.color" description="Link Color" type="color" default="#2563eb" value="#2563eb"/>
   <Variable name="link.hover.color" description="Link Hover Color" type="color" default="#1d4ed8" value="#1d4ed8"/>
*/

:root {
  --bg: #f8fafc;
  --surface: #ffffff;
  --surface-2: #f1f5f9;
  --surface-glass: rgba(255, 255, 255, 0.86);
  --text: #0f172a;
  --text-muted: #475569;
  --text-soft: #64748b;
  --border: #e2e8f0;
  --border-strong: #cbd5e1;
  --accent: #2563eb;
  --accent-2: #7c3aed;
  --accent-soft: rgba(37, 99, 235, 0.1);
  --danger: #ef4444;
  --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.05);
  --shadow-md: 0 10px 28px -8px rgba(15, 23, 42, 0.09);
  --shadow-lg: 0 20px 45px -15px rgba(15, 23, 42, 0.14);
  --radius-sm: 10px;
  --radius-md: 16px;
  --radius-lg: 22px;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-display: 'Plus Jakarta Sans', 'Inter', -apple-system, sans-serif;
  --font-serif: 'Newsreader', Georgia, serif;
}

html[data-theme="dark"] {
  --bg: #070b14;
  --surface: #111827;
  --surface-2: #1e293b;
  --surface-glass: rgba(17, 24, 39, 0.86);
  --text: #f8fafc;
  --text-muted: #cbd5e1;
  --text-soft: #94a3b8;
  --border: rgba(148, 163, 184, 0.16);
  --border-strong: rgba(148, 163, 184, 0.28);
  --accent: #38bdf8;
  --accent-2: #a78bfa;
  --accent-soft: rgba(56, 189, 248, 0.14);
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.35);
  --shadow-md: 0 12px 30px -10px rgba(0, 0, 0, 0.5);
  --shadow-lg: 0 24px 50px -15px rgba(0, 0, 0, 0.65);
}

*, *::before, *::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.65;
  overflow-x: hidden;
  transition: background-color 0.2s ease, color 0.2s ease;
}

a {
  color: var(--accent);
  text-decoration: none;
  transition: color 0.15s ease, opacity 0.15s ease;
}

a:hover {
  color: var(--accent-2);
}

img {
  max-width: 100%;
  height: auto;
}

/* Hide legacy Blogger bar while keeping Navbar widget valid */
#navbar, #Navbar1, .navbar {
  display: none !important;
  height: 0 !important;
  overflow: hidden !important;
}

/* Reading progress bar on post pages */
#read-progress {
  position: fixed;
  top: 0;
  left: 0;
  width: 0%;
  height: 3px;
  z-index: 9999;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  transition: width 0.08s linear;
}

.container-max {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 20px;
}

/* Live Breaking News Ticker */
.ticker-bar {
  background: #0f172a;
  color: #e2e8f0;
  font-size: 13px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.ticker-inner {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 38px;
  padding: 6px 0;
}

.live-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border-radius: 999px;
  background: rgba(239, 68, 68, 0.18);
  color: #fca5a5;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  flex-shrink: 0;
}

.live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #ef4444;
  box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.7);
  animation: pulseDot 1.8s infinite;
}

@keyframes pulseDot {
  0% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.7); }
  70% { box-shadow: 0 0 0 7px rgba(239, 68, 68, 0); }
  100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
}

.ticker-link-wrap {
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ticker-link-wrap a {
  color: #f8fafc;
  font-weight: 500;
}

.ticker-link-wrap a:hover {
  color: #38bdf8;
  text-decoration: underline;
}

.ticker-date {
  color: #94a3b8;
  font-size: 12px;
  flex-shrink: 0;
}

.ticker-controls {
  display: inline-flex;
  gap: 4px;
  flex-shrink: 0;
}

.ticker-btn {
  width: 24px;
  height: 24px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.06);
  color: #e2e8f0;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
}

.ticker-btn:hover {
  background: rgba(255, 255, 255, 0.16);
}

/* Sticky Glassmorphic Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 900;
  background: var(--surface-glass);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
}

.header-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 0;
}

.brand-wrap {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.brand-logo {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #ffffff;
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 8px 18px -6px rgba(37, 99, 235, 0.55);
  flex-shrink: 0;
}

.header .titlewrapper h1,
.header .titlewrapper p.title,
.brand-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  line-height: 1.15;
  color: var(--text);
}

.header .titlewrapper a {
  color: var(--text);
}

.header .descriptionwrapper p.description {
  margin: 2px 0 0;
  font-size: 12px;
  color: var(--text-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.search-pill {
  position: relative;
  display: flex;
  align-items: center;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 4px 6px 4px 14px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.search-pill:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.search-pill input {
  border: 0;
  outline: none;
  background: transparent;
  color: var(--text);
  font-family: inherit;
  font-size: 13.5px;
  width: 190px;
}

.search-pill input::placeholder {
  color: var(--text-soft);
}

.search-pill button {
  border: 0;
  border-radius: 999px;
  padding: 6px 13px;
  background: var(--accent);
  color: #ffffff;
  font-weight: 600;
  font-size: 12.5px;
  cursor: pointer;
}

.search-pill button:hover {
  opacity: 0.92;
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 36px;
  padding: 0 12px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.15s ease, border-color 0.15s ease, background 0.15s ease;
}

.icon-btn:hover {
  border-color: var(--accent);
  background: var(--surface-2);
}

.theme-icon-sun,
.theme-icon-moon {
  width: 16px;
  height: 16px;
  display: inline-block;
}

html[data-theme="dark"] .theme-icon-moon { display: none; }
html[data-theme="light"] .theme-icon-sun { display: none; }

/* Category Navigation Strip */
.cat-nav-wrap {
  border-top: 1px solid var(--border);
  background: transparent;
}

.cat-nav {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  scrollbar-width: none;
  padding: 9px 0;
}

.cat-nav::-webkit-scrollbar {
  display: none;
}

.cat-nav a {
  flex-shrink: 0;
  padding: 5px 13px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-muted);
  background: transparent;
  border: 1px solid transparent;
  transition: all 0.15s ease;
}

.cat-nav a:hover {
  color: var(--text);
  background: var(--surface-2);
}

.cat-nav a.is-active {
  color: #ffffff;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  box-shadow: 0 4px 12px -4px rgba(37, 99, 235, 0.5);
}

/* Main Shell Grid */
.site-shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 28px;
  padding-top: 24px;
  padding-bottom: 48px;
  align-items: start;
}

/* Section bar above feed */
.feed-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 18px;
}

.feed-heading {
  margin: 0;
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 8px;
}

.feed-heading::before {
  content: "";
  display: inline-block;
  width: 5px;
  height: 20px;
  border-radius: 999px;
  background: linear-gradient(180deg, var(--accent), var(--accent-2));
}

.view-toggle {
  display: inline-flex;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 3px;
  gap: 2px;
}

.view-toggle button {
  border: 0;
  background: transparent;
  color: var(--text-soft);
  font-family: inherit;
  font-size: 12.5px;
  font-weight: 600;
  padding: 5px 11px;
  border-radius: 7px;
  cursor: pointer;
}

.view-toggle button.is-active {
  background: var(--surface);
  color: var(--text);
  box-shadow: var(--shadow-sm);
}

/* Filter/Search status banner */
.status-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  margin-bottom: 18px;
  border-radius: var(--radius-sm);
  background: var(--accent-soft);
  border: 1px solid rgba(37, 99, 235, 0.25);
  font-size: 14px;
  color: var(--text);
}

.status-banner a {
  font-weight: 700;
  white-space: nowrap;
}

/* Magazine Post Cards Grid */
.posts-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

body.list-mode .posts-grid {
  grid-template-columns: minmax(0, 1fr);
}

.post-card {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}

.post-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--border-strong);
}

/* Featured Hero Card for #1 Homepage Post */
.post-card.is-hero {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  min-height: 290px;
}

body.list-mode .post-card:not(.is-hero) {
  display: grid;
  grid-template-columns: 240px 1fr;
}

body.list-mode .post-card.is-text-card:not(.is-hero) {
  grid-template-columns: minmax(0, 1fr);
}

/* Text-only grid cards (no thumbnail / filtered icon) drop bulky box and become crisp editorial cards */
.post-card.is-text-card:not(.is-hero)::before {
  content: "";
  display: block;
  height: 4px;
  width: 100%;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
}

.post-card.is-text-card:not(.is-hero):nth-child(4n+2)::before {
  background: linear-gradient(90deg, #0d9488, #0284c7);
}

.post-card.is-text-card:not(.is-hero):nth-child(4n+3)::before {
  background: linear-gradient(90deg, #db2777, #7c3aed);
}

.post-card.is-text-card:not(.is-hero):nth-child(4n+4)::before {
  background: linear-gradient(90deg, #2563eb, #06b6d4);
}

.post-card.is-text-card:not(.is-hero) .card-media {
  display: none;
}

.card-meta-cat {
  color: var(--accent);
  font-weight: 600;
}

.post-card.is-text-card:not(.is-hero) .card-meta-cat {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.02em;
  background: var(--accent-soft);
  color: var(--accent);
}

.post-card.is-text-card:not(.is-hero) .card-meta-sep {
  display: none;
}

.post-card.is-text-card:not(.is-hero) .card-meta-top {
  justify-content: space-between;
  flex-direction: row-reverse;
}

.post-card.is-text-card:not(.is-hero) .card-excerpt {
  -webkit-line-clamp: 4;
}

.crosscol-wrap:has(#crosscol:empty) {
  display: none;
}

.card-media {
  position: relative;
  display: block;
  overflow: hidden;
  aspect-ratio: 16 / 10;
  background: linear-gradient(135deg, #1d4ed8 0%, #6d28d9 100%);
}

.post-card.is-hero .card-media {
  aspect-ratio: auto;
  height: 100%;
  min-height: 290px;
  max-height: 360px;
}

body.list-mode .post-card:not(.is-hero) .card-media {
  aspect-ratio: auto;
  height: 100%;
  min-height: 165px;
  max-height: 210px;
}

.card-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}

.post-card:hover .card-media img {
  transform: scale(1.05);
}

/* Graceful gradient spotlight visual when Hero or media falls back without duplicating the headline */
.card-fallback {
  width: 100%;
  height: 100%;
  padding: 56px 28px 28px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  position: relative;
  color: #ffffff;
  background: radial-gradient(circle at 85% 15%, rgba(56, 189, 248, 0.38), transparent 52%),
              radial-gradient(circle at 15% 85%, rgba(168, 85, 247, 0.35), transparent 55%),
              linear-gradient(135deg, #0f172a 0%, #1e3a8a 52%, #4338ca 100%);
}

.card-fallback::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(rgba(255, 255, 255, 0.14) 1px, transparent 1px);
  background-size: 18px 18px;
  opacity: 0.45;
  pointer-events: none;
}

.fallback-kicker {
  position: relative;
  display: inline-flex;
  align-items: center;
  width: fit-content;
  padding: 4px 11px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.14);
  border: 1px solid rgba(255, 255, 255, 0.22);
  font-family: var(--font-display);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 12px;
}

.fallback-title {
  position: relative;
  font-family: var(--font-serif);
  font-style: normal;
  font-weight: 500;
  font-size: 1.55rem;
  line-height: 1.28;
  letter-spacing: -0.01em;
  color: #ffffff;
}

.fallback-sub {
  position: relative;
  margin-top: 8px;
  font-size: 13px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.78);
}

.empty-state-card {
  background: var(--surface);
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius-md);
  padding: 36px 24px;
  text-align: center;
  color: var(--text-muted);
}

.card-badge-row {
  position: absolute;
  top: 12px;
  left: 12px;
  right: 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  pointer-events: none;
}

.card-chip {
  pointer-events: auto;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: #ffffff;
  background: rgba(15, 23, 42, 0.72);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.18);
}

.card-chip.is-featured {
  background: linear-gradient(135deg, #2563eb, #7c3aed);
  border-color: transparent;
}

.card-body {
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.post-card.is-hero .card-body {
  padding: 26px 28px;
  justify-content: center;
}

.card-meta-top {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-soft);
  margin-bottom: 8px;
}

.card-title {
  margin: 0 0 10px;
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 700;
  line-height: 1.34;
  letter-spacing: -0.015em;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.post-card.is-hero .card-title {
  font-size: 1.6rem;
  line-height: 1.25;
}

.card-title a {
  color: var(--text);
}

.card-title a:hover {
  color: var(--accent);
}

.card-excerpt {
  margin: 0 0 16px;
  color: var(--text-muted);
  font-size: 14px;
  line-height: 1.58;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.post-card.is-hero .card-excerpt {
  -webkit-line-clamp: 3;
  font-size: 15px;
}

.card-footer {
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font-size: 12.5px;
  color: var(--text-soft);
}

.card-actions {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.mini-share-btn {
  border: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--text-muted);
  border-radius: 8px;
  padding: 4px 9px;
  font-size: 11.5px;
  font-weight: 600;
  cursor: pointer;
}

.mini-share-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.read-cta {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-weight: 700;
  color: var(--accent);
}

/* Single Article Page View */
.article-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px 34px;
  box-shadow: var(--shadow-md);
}

.breadcrumbs {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  font-size: 13px;
  color: var(--text-soft);
  margin-bottom: 14px;
}

.article-labels {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 14px;
}

.tag-pill {
  display: inline-flex;
  align-items: center;
  padding: 4px 12px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  background: var(--accent-soft);
  color: var(--accent);
  border: 1px solid rgba(37, 99, 235, 0.18);
}

.tag-pill:hover {
  background: var(--accent);
  color: #ffffff;
}

.article-title {
  margin: 0 0 18px;
  font-family: var(--font-display);
  font-size: clamp(1.55rem, 2.8vw, 2.25rem);
  font-weight: 800;
  line-height: 1.22;
  letter-spacing: -0.025em;
  color: var(--text);
}

.article-meta-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px;
  padding: 14px 0;
  margin-bottom: 24px;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.author-inline {
  display: flex;
  align-items: center;
  gap: 10px;
}

.author-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #ffffff;
  font-weight: 800;
  font-family: var(--font-display);
  font-size: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.meta-sub {
  font-size: 12.5px;
  color: var(--text-soft);
}

.share-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.share-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 12px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--text);
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
}

.share-chip:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.post-prose {
  font-size: 1.0625rem;
  line-height: 1.8;
  color: var(--text);
}

.post-prose p {
  margin: 0 0 1.2em;
}

.post-prose img {
  border-radius: 12px;
  margin: 10px 0;
  box-shadow: var(--shadow-sm);
}

.post-prose a {
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.post-prose blockquote {
  margin: 20px 0;
  padding: 14px 18px;
  border-left: 4px solid var(--accent);
  background: var(--surface-2);
  border-radius: 0 10px 10px 0;
  font-family: var(--font-serif);
  font-style: italic;
}

/* Related Stories Widget (auto-loaded on item pages) */
.related-section {
  margin-top: 28px;
}

.related-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.related-mini {
  background: var(--surface);
  border: 1px solid var(--border);
  border-top: 3px solid var(--accent);
  border-radius: var(--radius-sm);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.related-mini:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.related-mini img {
  width: 100%;
  height: 112px;
  object-fit: cover;
}

.related-mini-body {
  padding: 13px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.related-mini-title {
  font-family: var(--font-display);
  font-size: 13.5px;
  font-weight: 700;
  line-height: 1.38;
  color: var(--text);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.related-mini-meta {
  font-size: 11.5px;
  font-weight: 600;
  color: var(--accent);
}

/* Pagination Pills */
.blog-pager {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 28px;
}

.blog-pager a,
.pager-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 18px;
  border-radius: 999px;
  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--text);
  font-weight: 600;
  font-size: 13.5px;
  box-shadow: var(--shadow-sm);
}

.blog-pager a:hover {
  border-color: var(--accent);
  color: var(--accent);
}

/* Sidebar Cards & Dynamic Interactive Tabs */
.sidebar-col {
  display: flex;
  flex-direction: column;
  gap: 20px;
  position: sticky;
  top: 114px;
}

.sidebar .widget,
.side-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 18px 20px;
  box-shadow: var(--shadow-sm);
}

.sidebar .widget h2,
.side-card h2 {
  margin: 0 0 14px;
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

/* Interactive Dynamic Sidebar Feed Tabs */
.dyn-tabs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin-bottom: 14px;
  background: var(--surface-2);
  padding: 4px;
  border-radius: 10px;
}

.dyn-tab {
  border: 0;
  background: transparent;
  color: var(--text-soft);
  font-family: var(--font-sans);
  font-size: 12px;
  font-weight: 700;
  padding: 6px 4px;
  border-radius: 7px;
  cursor: pointer;
}

.dyn-tab.is-active {
  background: var(--surface);
  color: var(--accent);
  box-shadow: var(--shadow-sm);
}

.dyn-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.dyn-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border);
}

.dyn-item:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.dyn-rank {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 14px;
  color: var(--accent);
  min-width: 22px;
  line-height: 1.3;
}

.dyn-item-title {
  font-size: 13.5px;
  font-weight: 600;
  line-height: 1.38;
  color: var(--text);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.dyn-item-date {
  font-size: 11.5px;
  color: var(--text-soft);
  margin-top: 3px;
}

/* Label cloud compact pill layout */
.Label ul {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.Label li {
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  max-width: 100%;
}

.Label li a,
.Label li > span:first-child {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  padding: 5px 11px;
  border-radius: 999px;
  font-size: 12.5px;
  font-weight: 600;
  background: var(--surface-2);
  color: var(--text-muted);
  border: 1px solid var(--border);
}

.Label li a:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.lbl-count {
  font-size: 11px;
  font-weight: 700;
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--surface);
  color: var(--text-soft);
  flex-shrink: 0;
  white-space: nowrap;
}

/* Feed widget list */
.Feed ul {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.Feed li {
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border);
  font-size: 13.5px;
  line-height: 1.4;
}

.Feed li:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

/* Profile widget */
.Profile .profile-img {
  border-radius: 50%;
  float: left;
  margin: 0 12px 8px 0;
  border: 2px solid var(--border);
}

.Profile .profile-datablock {
  margin: 0 0 8px;
}

.Profile .profile-data,
.Profile .profile-textblock {
  color: var(--text-muted);
  font-size: 13.5px;
  margin: 2px 0 0;
}

/* Comments */
.comments {
  margin-top: 28px;
  padding-top: 22px;
  border-top: 1px solid var(--border);
}

.comments h4 {
  font-family: var(--font-display);
  margin: 0 0 14px;
}

/* Footer */
.site-footer {
  margin-top: 20px;
  background: var(--surface);
  border-top: 1px solid var(--border);
  padding: 36px 0 64px;
  font-size: 13.5px;
  color: var(--text-soft);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 28px;
  margin-bottom: 24px;
}

.footer-col h3 {
  margin: 0 0 10px;
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 800;
  color: var(--text);
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.footer-links a {
  color: var(--text-muted);
}

.footer-links a:hover {
  color: var(--accent);
}

.footer-bottom {
  padding-top: 18px;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
}

/* Toast Notification & Back to Top */
#fss-toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translate(-50%, 16px);
  background: #0f172a;
  color: #ffffff;
  padding: 10px 18px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 600;
  box-shadow: var(--shadow-lg);
  opacity: 0;
  pointer-events: none;
  z-index: 9999;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

#fss-toast.is-visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

#back-to-top {
  position: fixed;
  right: 20px;
  bottom: 24px;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  box-shadow: var(--shadow-md);
  cursor: pointer;
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 800;
  font-weight: 800;
}

#back-to-top.is-visible {
  display: inline-flex;
}

/* Blogger Layout Editor Support */
body#layout .site-shell {
  display: block;
}

body#layout .container-max {
  max-width: 820px;
}

/* Responsive Breakpoints */
@media only screen and (max-width: 1024px) {
  .site-shell {
    grid-template-columns: minmax(0, 1fr);
  }
  .sidebar-col {
    position: static;
  }
  .post-card.is-hero {
    grid-template-columns: minmax(0, 1fr);
  }
  .post-card.is-hero .card-media {
    min-height: 200px;
    max-height: 240px;
  }
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media only screen and (max-width: 720px) {
  .container-max {
    padding: 0 14px;
  }
  .ticker-date {
    display: none;
  }
  .header-main {
    flex-wrap: wrap;
    gap: 10px;
  }
  .header-actions {
    width: 100%;
    justify-content: space-between;
  }
  .search-pill {
    flex: 1;
  }
  .search-pill input {
    width: 100%;
  }
  .surprise-label {
    display: none;
  }
  .posts-grid,
  body.list-mode .posts-grid,
  .related-grid,
  .footer-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  body.list-mode .post-card:not(.is-hero) {
    grid-template-columns: minmax(0, 1fr);
  }
  .article-card {
    padding: 20px 18px;
  }
}

