(function() {
  var items = ;
  var msgs = ;
  var config = ;
  var render = function() {
    if (window.goog && window.goog.comments) {
      var holder = document.getElementById('comment-holder');
      window.goog.comments.render(holder, document.getElementById('comment-editor-src'), items, msgs, config);
    }
  };
  if (window.goog && window.goog.comments) { render(); }
  else {
    window.goog = window.goog || {};
    window.goog.comments = window.goog.comments || {};
    window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
    window.goog.comments.loadQueue.push(render);
  }
})();

body.script:
//
(function () {
  document.body.classList.remove('loading');

  // 1. Dynamic Monogram Initial & Footer Year
  var yearEl = document.getElementById('footer-year');
  if (yearEl) yearEl.textContent = new Date().getFullYear();

  var headerTitleEl = document.querySelector('.header .titlewrapper');
  var monogramEl = document.getElementById('brand-monogram');
  if (headerTitleEl && monogramEl) {
    var firstChar = (headerTitleEl.textContent || 'F').trim().charAt(0).toUpperCase();
    if (firstChar) monogramEl.textContent = firstChar;
  }

  // 2. Date Pill in Breaking Ticker
  var dateLabel = document.getElementById('today-date-label');
  if (dateLabel) {
    try {
      dateLabel.textContent = new Date().toLocaleDateString(undefined, {
        weekday: 'short', month: 'short', day: 'numeric', year: 'numeric'
      });
    } catch (e) {}
  }

  // 3. Dark / Light Mode Toggle
  var themeBtn = document.getElementById('theme-toggle');
  if (themeBtn) {
    themeBtn.addEventListener('click', function () {
      var current = document.documentElement.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';
      var next = current === 'dark' ? 'light' : 'dark';
      document.documentElement.setAttribute('data-theme', next);
      try { localStorage.setItem('fss-theme', next); } catch (e) {}
    });
  }

  // 4. Grid / List View Switcher
  var gridBtn = document.getElementById('view-grid-btn');
  var listBtn = document.getElementById('view-list-btn');
  function applyViewMode(mode) {
    var isList = mode === 'list';
    document.body.classList.toggle('list-mode', isList);
    if (gridBtn) gridBtn.classList.toggle('is-active', !isList);
    if (listBtn) listBtn.classList.toggle('is-active', isList);
    try { localStorage.setItem('fss-view', mode); } catch (e) {}
  }
  try {
    if (localStorage.getItem('fss-view') === 'list') applyViewMode('list');
  } catch (e) {}
  if (gridBtn) gridBtn.addEventListener('click', function () { applyViewMode('grid'); });
  if (listBtn) listBtn.addEventListener('click', function () { applyViewMode('list'); });

  // 5. Highlight Active Category Pill (exact path match)
  var pathNow = decodeURIComponent(window.location.pathname || '/').replace(/\/+$/, '') || '/';
  document.querySelectorAll('#cat-nav a').forEach(function (link) {
    var rawHref = link.getAttribute('href') || '';
    if (!rawHref || rawHref.charAt(0) === '#') return;
    var href = '';
    try {
      href = decodeURIComponent(new URL(link.href, window.location.origin).pathname).replace(/\/+$/, '') || '/';
    } catch (e) {
      return;
    }
    if (href === '/' && (pathNow === '/' || pathNow === '/index.html')) {
      link.classList.add('is-active');
    } else if (href !== '/' && pathNow.toLowerCase() === href.toLowerCase()) {
      link.classList.add('is-active');
    }
  });

  // 5b. Clean legacy IFTTT title prefixes (e.g. "NEWS:~", "STORY IN 50 WORDS😮:~")
  function cleanHeadline(str) {
    if (!str) return '';
    var cleaned = str.replace(/^(?:NEWS|STORY(?:\s+IN\s+50\s+WORDS)?)\s*[^a-zA-Z0-9"'\(\[]*[:~-]+\s*/i, '').trim();
    return cleaned || str.trim();
  }
  document.querySelectorAll('.card-title a, .article-title').forEach(function (el) {
    el.textContent = cleanHeadline(el.textContent);
  });

  // 6. Search Hotkey ("/")
  var searchInput = document.getElementById('header-search-input');
  document.addEventListener('keydown', function (ev) {
    if (ev.key === '/' && searchInput && !/INPUT|TEXTAREA|SELECT/.test((document.activeElement || {}).tagName)) {
      ev.preventDefault();
      searchInput.focus();
    }
  });

  // 7. Relative Time Formatter + Small-Icon/Tracker Thumbnail Fallback
  function formatRelTime(iso) {
    if (!iso) return '';
    var then = new Date(iso).getTime();
    if (isNaN(then)) return '';
    var diffSec = Math.floor((Date.now() - then) / 1000);
    if (diffSec < 60) return 'Just now';
    if (diffSec < 3600) return Math.floor(diffSec / 60) + 'm ago';
    if (diffSec < 86400) return Math.floor(diffSec / 3600) + 'h ago';
    if (diffSec < 604800) return Math.floor(diffSec / 86400) + 'd ago';
    return new Date(then).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
  }
  document.querySelectorAll('.js-rel-time').forEach(function (el) {
    var txt = formatRelTime(el.getAttribute('datetime'));
    if (txt) el.textContent = txt;
  });

  function isBadThumbUrl(url) {
    var src = (url || '').toLowerCase();
    if (!src) return true;
    return src.indexOf('feedburner.com') !== -1 ||
           src.indexOf('feedproxy.google.com') !== -1 ||
           src.indexOf('/emoji/') !== -1 ||
           src.indexOf('twemoji') !== -1 ||
           src.indexOf('/s72-c/') !== -1;
  }
  function showCardFallback(img) {
    img.style.display = 'none';
    var card = img.closest('.post-card');
    if (card) card.classList.add('is-text-card');
    var fb = img.parentElement && img.parentElement.querySelector('.card-fallback');
    if (fb) fb.style.display = 'flex';
  }
  document.querySelectorAll('.js-card-img').forEach(function (img) {
    if (isBadThumbUrl(img.getAttribute('src'))) {
      showCardFallback(img);
      return;
    }
    if (img.complete) {
      if (img.naturalWidth < 140 || img.naturalHeight < 90) showCardFallback(img);
    } else {
      img.addEventListener('load', function () {
        if (img.naturalWidth < 140 || img.naturalHeight < 90) showCardFallback(img);
      });
      img.addEventListener('error', function () {
        showCardFallback(img);
      });
    }
  });

  // 8. Article Reading Time & Progress Bar
  var proseEl = document.querySelector('.post-prose');
  var readTimeEl = document.querySelector('.js-read-time');
  if (proseEl && readTimeEl) {
    var words = (proseEl.textContent || '').trim().split(/\s+/).filter(Boolean).length;
    var mins = Math.max(1, Math.ceil(words / 200));
    readTimeEl.textContent = mins + ' min read';
  }

  var progressEl = document.getElementById('read-progress');
  var topBtn = document.getElementById('back-to-top');
  window.addEventListener('scroll', function () {
    var scrollTop = window.scrollY || document.documentElement.scrollTop || 0;
    if (topBtn) topBtn.classList.toggle('is-visible', scrollTop > 400);
    if (progressEl && proseEl) {
      var docH = document.documentElement.scrollHeight - window.innerHeight;
      var pct = docH > 0 ? Math.min(100, Math.max(0, (scrollTop / docH) * 100)) : 0;
      progressEl.style.width = pct + '%';
    }
  }, { passive: true });
  if (topBtn) topBtn.addEventListener('click', function () { window.scrollTo({ top: 0, behavior: 'smooth' }); });

  // 9. Share Copy Link & Toast
  var toast = document.getElementById('fss-toast');
  var toastTimer = null;
  function showToast(msg) {
    if (!toast) return;
    toast.textContent = msg;
    toast.classList.add('is-visible');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { toast.classList.remove('is-visible'); }, 2200);
  }
  document.querySelectorAll('.js-copy-link').forEach(function (btn) {
    btn.addEventListener('click', function (e) {
      e.preventDefault();
      var url = btn.getAttribute('data-url') || window.location.href;
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(url).then(function () { showToast('Link copied to clipboard'); });
      } else {
        showToast(url);
      }
    });
  });

  // 10. Author Initial Avatar on Item Pages
  var avatarEl = document.querySelector('.author-avatar');
  var authorNameEl = document.querySelector('.author-name-text');
  if (avatarEl && authorNameEl) {
    var nameTxt = (authorNameEl.textContent || '').trim();
    if (nameTxt) avatarEl.textContent = nameTxt.charAt(0).toUpperCase();
  }

  // 11. Collapse Long Label Cloud (>18 labels) cleanly
  var labelUl = document.querySelector('.Label ul');
  if (labelUl && labelUl.children.length > 18) {
    var allItems = Array.prototype.slice.call(labelUl.children);
    allItems.slice(18).forEach(function (li) { li.style.display = 'none'; });
    var toggleMore = document.createElement('button');
    toggleMore.type = 'button';
    toggleMore.className = 'mini-share-btn';
    toggleMore.style.marginTop = '12px';
    toggleMore.textContent = 'Show all ' + allItems.length + ' topics';
    var expanded = false;
    toggleMore.addEventListener('click', function () {
      expanded = !expanded;
      allItems.slice(18).forEach(function (li) { li.style.display = expanded ? '' : 'none'; });
      toggleMore.textContent = expanded ? 'Show fewer topics' : 'Show all ' + allItems.length + ' topics';
    });
    labelUl.parentElement.appendChild(toggleMore);
  }

  // 12. Dynamic Blogger JSONP Loader (Ticker, Sidebar Explorer, Surprise Me, Related Stories)
  function loadBloggerFeed(label, maxResults, cbName, onLoaded) {
    window[cbName] = function (json) {
      try {
        var entries = (json && json.feed && json.feed.entry) || [];
        var posts = entries.map(function (entry) {
          var alt = (entry.link || []).find(function (l) { return l.rel === 'alternate'; });
          var thumb = (entry['media$thumbnail'] && entry['media$thumbnail'].url) || '';
          if (thumb) thumb = thumb.replace(/\/s\d+(-c)?\//, '/w500/');
          var cats = (entry.category || []).map(function (c) { return c.term; });
          return {
            id: (entry.id && entry.id.$t) || '',
            title: cleanHeadline((entry.title && entry.title.$t) || 'Untitled'),
            url: (alt && alt.href) || '#',
            published: (entry.published && entry.published.$t) || '',
            thumb: thumb,
            label: cats[0] || ''
          };
        });
        onLoaded(posts);
      } catch (e) {}
    };
    var base = '/feeds/posts/default' + (label ? '/-/' + encodeURIComponent(label) : '');
    var s = document.createElement('script');
    s.src = base + '?alt=json-in-script&max-results=' + maxResults + '&callback=' + cbName;
    s.async = true;
    document.body.appendChild(s);
  }

  // 12a. Live Ticker + Surprise Me Pool
  var tickerItems = [];
  var tickerIdx = 0;
  var tickerAnchor = document.getElementById('ticker-headline');
  function renderTicker() {
    if (!tickerAnchor || !tickerItems.length) return;
    var item = tickerItems[tickerIdx];
    tickerAnchor.textContent = (item.label ? '[' + item.label + '] ' : '') + item.title;
    tickerAnchor.href = item.url;
  }
  loadBloggerFeed('', 12, 'fssTickerFeedCb', function (posts) {
    if (!posts.length) {
      if (tickerAnchor) tickerAnchor.textContent = 'Fresh News, Trending Updates & 50-Word Short Stories';
      return;
    }
    tickerItems = posts;
    renderTicker();
    renderSidebarList(posts.slice(0, 5));
    setInterval(function () {
      if (!tickerItems.length) return;
      tickerIdx = (tickerIdx + 1) % tickerItems.length;
      renderTicker();
    }, 5000);
  });
  var prevBtn = document.getElementById('ticker-prev');
  var nextBtn = document.getElementById('ticker-next');
  if (prevBtn) prevBtn.addEventListener('click', function () {
    if (!tickerItems.length) return;
    tickerIdx = (tickerIdx - 1 + tickerItems.length) % tickerItems.length;
    renderTicker();
  });
  if (nextBtn) nextBtn.addEventListener('click', function () {
    if (!tickerItems.length) return;
    tickerIdx = (tickerIdx + 1) % tickerItems.length;
    renderTicker();
  });

  var surpriseBtn = document.getElementById('surprise-btn');
  if (surpriseBtn) {
    surpriseBtn.addEventListener('click', function () {
      if (!tickerItems.length) {
        showToast('Publish a few posts first to shuffle stories!');
        return;
      }
      var pick = tickerItems[Math.floor(Math.random() * tickerItems.length)];
      if (pick && pick.url && pick.url !== '#') window.location.href = pick.url;
    });
  }

  // 12b. Dynamic Sidebar Explorer Tabs
  var sidebarListEl = document.getElementById('dyn-sidebar-list');
  function renderSidebarList(posts) {
    if (!sidebarListEl) return;
    sidebarListEl.innerHTML = '';
    if (!posts.length) {
      sidebarListEl.innerHTML = '<div style="font-size:13px;color:var(--text-soft);">No posts in this section yet.</div>';
      return;
    }
    posts.forEach(function (p, idx) {
      var row = document.createElement('a');
      row.className = 'dyn-item';
      row.href = p.url;
      var rank = document.createElement('span');
      rank.className = 'dyn-rank';
      rank.textContent = (idx + 1 < 10 ? '0' : '') + (idx + 1);
      var info = document.createElement('div');
      var title = document.createElement('div');
      title.className = 'dyn-item-title';
      title.textContent = p.title;
      var meta = document.createElement('div');
      meta.className = 'dyn-item-date';
      meta.textContent = formatRelTime(p.published) || p.label;
      info.appendChild(title);
      info.appendChild(meta);
      row.appendChild(rank);
      row.appendChild(info);
      sidebarListEl.appendChild(row);
    });
  }

  var tabCounter = 0;
  var labelFallbackMap = {
    'Short Stories': ['Short Stories', 'short stories', 'SHORT STORIES IN 50WORDS', '50-Word Stories'],
    'News': ['News', 'Latest All News', 'NDTV News- Special', 'NDTV News - Special', 'Latest International News']
  };
  function loadWithLabelFallback(candidates, idx, countId) {
    var lbl = candidates[idx] || '';
    loadBloggerFeed(lbl, 5, 'fssSidebarCb_' + countId + '_' + idx, function (posts) {
      if ((!posts || !posts.length) && idx + 1 < candidates.length) {
        loadWithLabelFallback(candidates, idx + 1, countId);
      } else {
        renderSidebarList(posts);
      }
    });
  }
  document.querySelectorAll('.dyn-tab').forEach(function (tab) {
    tab.addEventListener('click', function () {
      document.querySelectorAll('.dyn-tab').forEach(function (t) { t.classList.remove('is-active'); });
      tab.classList.add('is-active');
      var lbl = tab.getAttribute('data-feed-label') || '';
      if (sidebarListEl) sidebarListEl.innerHTML = '<div style="font-size:13px;color:var(--text-soft);">Loading...</div>';
      tabCounter += 1;
      var candidates = lbl ? (labelFallbackMap[lbl] || [lbl]) : [''];
      loadWithLabelFallback(candidates, 0, tabCounter);
    });
  });

  // 12c. Related Posts on Article Pages
  var articleCard = document.querySelector('.article-card');
  if (articleCard) {
    var firstTagEl = articleCard.querySelector('.tag-pill');
    var firstLabel = firstTagEl ? (firstTagEl.textContent || '').trim() : '';
    var currentPostId = articleCard.getAttribute('data-post-id') || '';
    loadBloggerFeed(firstLabel, 6, 'fssRelatedCb', function (posts) {
      var filtered = posts.filter(function (p) {
        return p.url !== window.location.href && (!currentPostId || p.id.indexOf(currentPostId) === -1);
      }).slice(0, 3);
      if (!filtered.length) return;
      var sec = document.getElementById('related-section');
      var grid = document.getElementById('related-grid');
      if (!sec || !grid) return;
      grid.innerHTML = '';
      filtered.forEach(function (p) {
        var card = document.createElement('a');
        card.className = 'related-mini';
        card.href = p.url;
        if (p.thumb && !isBadThumbUrl(p.thumb)) {
          var im = document.createElement('img');
          im.src = p.thumb;
          im.alt = p.title;
          im.loading = 'lazy';
          im.addEventListener('error', function () { im.remove(); });
          card.appendChild(im);
        }
        var body = document.createElement('div');
        body.className = 'related-mini-body';
        var meta = document.createElement('span');
        meta.className = 'related-mini-meta';
        meta.textContent = p.label || formatRelTime(p.published) || 'Story';
        var ttl = document.createElement('div');
        ttl.className = 'related-mini-title';
        ttl.textContent = p.title;
        body.appendChild(meta);
        body.appendChild(ttl);
        card.appendChild(body);
        grid.appendChild(card);
      });
      sec.style.display = 'block';
    });
  }
})();
//
